with filtered as (select id, account_id, txn_type, amount, txn_time, merchant, is_flagged, substring(txn_type, 1, 3) as txn_type_prefix, length(merchant) as merchant_length, coalesce(merchant, 'NONE') as merchant_clean from transactions where amount < 3300), flagged as (select *, case when txn_time - lag(txn_time) over (partition by account_id order by txn_time, id) > interval '30' day then 1 else 0 end as session_start_flag from filtered), sessionized as (select *, sum(session_start_flag) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as session_id from flagged) select merchant, count(*) as cnt, count(*) as cnt_2, round(sum(session_start_flag) / nullif(count(case when txn_type = 'DEBIT' then 1 end), 0), 2) as session_start_flag_per_debit, min(txn_time) as first_txn_time, percentile_approx(merchant_length, array(0.25, 0.5, 0.75)) as merchant_length_quartiles, round(sum(merchant_length) / nullif(count(case when txn_type = 'REFUND' then 1 end), 0), 2) as merchant_length_per_refund from sessionized group by merchant order by cnt desc
